CREATE DEFINER=`root`@`localhost` PROCEDURE `SeedAICSData` ()   BEGIN
    DECLARE i INT DEFAULT 1;
    DECLARE rand_days INT;
    DECLARE rand_date DATE;
    DECLARE rand_age INT;
    DECLARE rand_birth_year INT;
    DECLARE rand_birth_date DATE;
    
    DECLARE v_fname VARCHAR(50);
    DECLARE v_mname VARCHAR(50);
    DECLARE v_lname VARCHAR(50);
    DECLARE v_sex VARCHAR(10);
    DECLARE v_civil VARCHAR(20);
    DECLARE v_brgy VARCHAR(50);
    DECLARE v_cat VARCHAR(100);
    DECLARE v_subcat VARCHAR(100);
    DECLARE v_cause VARCHAR(100);
    DECLARE v_assist VARCHAR(100);
    DECLARE new_id INT;

    WHILE i <= 2501 DO
        SET rand_days = FLOOR(RAND() * 91);
        SET rand_date = DATE_ADD('2022-09-01', INTERVAL rand_days DAY);
        
        SET v_sex = ELT(FLOOR(1 + RAND() * 2), 'Male', 'Female');
        SET v_civil = ELT(FLOOR(1 + RAND() * 5), 'Single', 'Married', 'Widowed', 'Separated', 'Common-law');
        SET v_brgy = ELT(FLOOR(1 + RAND() * 10), 'Batasan Hills', 'Commonwealth', 'Payatas', 'San Bartolome', 'Tandang Sora', 'Holy Spirit', 'Culiat', 'Fairview', 'Bagbag', 'Tatalon');
        
        SET v_fname = ELT(FLOOR(1 + RAND() * 8), 'Juan', 'Maria', 'Jose', 'Ana', 'Manuel', 'Pedro', 'Elena', 'Carlos');
        SET v_mname = ELT(FLOOR(1 + RAND() * 5), 'Santos', 'Reyes', 'Cruz', 'Bautista', 'Garcia');
        SET v_lname = ELT(FLOOR(1 + RAND() * 6), 'Gonzalez', 'Mercado', 'Perez', 'Aquino', 'Dizon', 'Villanueva');

        IF RAND() <= 0.35 THEN
            SET rand_age = FLOOR(60 + (RAND() * 26));
            SET v_cat = 'Senior Citizens';
        ELSE
            SET rand_age = FLOOR(18 + (RAND() * 42));
            SET v_cat = ELT(FLOOR(1 + RAND() * 3), 'Family Heads and Other Needy Adult', 'Persons with Disabilities', 'Men/Women in Specially Difficult Circumstances');
        END IF;

        SET rand_birth_year = 2022 - rand_age;
        -- SAFE DATE FALLBACK: Avoids illegal 02-30 or 04-31 combinations that cause silent failures
        SET rand_birth_date = STR_TO_DATE(CONCAT(rand_birth_year, '-06-', FLOOR(1 + RAND() * 28)), '%Y-%m-%d');

        IF RAND() <= 0.75 THEN
            SET v_assist = ELT(FLOOR(1 + RAND() * 5), 'Chemotherapy Assistance', 'Dialysis Assistance', 'Medical Cash Aid', 'Medicine Assistance', 'Hospital Bill Assistance');
        ELSE
            SET v_assist = ELT(FLOOR(1 + RAND() * 3), 'Cash Guarantee', 'Surgery Financial Support', 'Laboratory Assistance');
        END IF;

        SET v_cause = ELT(FLOOR(1 + RAND() * 5), 'Medication Assistance', 'Medical Checkup', 'Emergency Treatment', 'Chemotherapy', 'Dialysis');
        SET v_subcat = ELT(FLOOR(1 + RAND() * 4), 'Individuals with Cancer', 'Dialysis Patients', 'Chronic Illness / Geriatric Conditions', 'Physical Disability');

            request_date, medical_cause, assistance_type, status, 
            fname, mname, lname, birth_date, sex, civil_status, 
            barangay, client_category, client_subcategory
        ) VALUES (
            rand_date, v_cause, v_assist, 'Approved', 
            v_fname, v_mname, v_lname, rand_birth_date, v_sex, v_civil, 
            v_brgy, v_cat, v_subcat
        );

        SET new_id = LAST_INSERT_ID();
        UPDATE aics_sample_data SET id_number = CONCAT('QC-', new_id) WHERE id = new_id;

        SET i = i + 1;
    END WHILE;
END$$

